def cancelingStampsFloorTicket(readings):
    a=readings
    out=[]
    for x in a:
        if out and out[-1]==x: out.pop()
        else: out.append(x)
    return min(out,default=0)


java
class Solution {
  public int cancelingStampsFloorTicket(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){if(!out.isEmpty()&&out.get(out.size()-1)==x)out.remove(out.size()-1);else out.add(x);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
